  assert.deepEqual(await lab.locator('[data-imaging-ruler=object] [data-imaging-ruler-mark]').allTextContents(),['透鏡0F','F','2F','3F','3.5F']);assert.deepEqual(await lab.locator('[data-imaging-ruler=screen] [data-imaging-ruler-mark]').allTextContents(),['透鏡0F','F','2F','3F','4F','5F']);const cases=[];
