 async function checkRuler(p=page){const rows=await p.evaluate(()=>{const q=window.__imaging,r=q.read(),root=document.querySelector('#lab4');return ['object','screen'].map(key=>{const h=root.querySelector(`[data-imaging-ruler-handle=${key}]`),track=root.querySelector(`[data-imaging-ruler-track=${key}]`).getBoundingClientRect(),box=h.getBoundingClientRect(),fraction=key==='object'?1-r.state[key]/q.G.objectMax:r.state[key]/q.G.screenMax;return{key,hidden:h.hidden,value:r.state[key],handle:Number(h.getAttribute('aria-valuenow')),width:track.width,pixel:(box.left+box.right)/2,expectedPixel:track.left+fraction*track.width,model:r.studio?(key==='object'?-r.studio.source.position.x:r.studio.screen.position.x)/q.G.scale:undefined};});});for(const q of rows){assert.ok(Math.abs(q.handle-q.value/100)<1e-10,JSON.stringify(q));if(q.width&&!q.hidden)assert.ok(Math.abs(q.pixel-q.expectedPixel)<.15,JSON.stringify(q));if(q.model!==undefined)assert.ok(Math.abs(q.model-q.value)<1e-8);}}
